package com.campusradar.accountdata;
import com.campusradar.common.*;
import com.campusradar.resume.PrivateFileStorage;
import com.campusradar.task.TaskService;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.datasource.*;
import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
class AccountDataTest {
    AccountDataService service;JdbcTemplate db;Clock clock=Clock.fixed(Instant.parse("2026-10-28T08:00:00Z"),ZoneOffset.UTC);String user="11111111-1111-4111-8111-111111111111";
    @BeforeEach void setup(){var source=new DriverManagerDataSource("jdbc:h2:mem:accountdata;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","sa","");db=new JdbcTemplate(source);db.execute("DROP ALL OBJECTS");db.execute("CREATE TABLE users(id VARCHAR PRIMARY KEY,status VARCHAR,data_operation VARCHAR,data_revision INT,auth_version INT)");db.update("INSERT INTO users VALUES(?,'ACTIVE','IDLE',7,1)",user);db.execute("CREATE TABLE tasks(id VARCHAR PRIMARY KEY,user_id VARCHAR,type VARCHAR,state VARCHAR,payload VARCHAR,dedup_key VARCHAR,next_attempt_at TIMESTAMP,progress INT DEFAULT 0,attempt INT DEFAULT 0,result_file_id VARCHAR,error_code VARCHAR,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");db.execute("CREATE TABLE outbox_events(id VARCHAR,event_type VARCHAR,aggregate_id VARCHAR,routing_key VARCHAR,payload VARCHAR,state VARCHAR,available_at TIMESTAMP)");db.execute("CREATE TABLE idempotency_records(id VARCHAR PRIMARY KEY,user_id VARCHAR,method VARCHAR,route_hash VARCHAR,idem_key VARCHAR,request_hash VARCHAR,http_status INT,response_body VARCHAR,expires_at TIMESTAMP)");var json=JsonMapper.builder().build();var rows=new SqlRows(new NamedParameterJdbcTemplate(source),json);var owners=new OwnerTransactions(rows,new DataSourceTransactionManager(source));var codec=new BackupCodec(json,clock,Base64.getEncoder().encodeToString(new byte[32]),"","test");service=new AccountDataService(rows,owners,new ContractInputs(json),new TaskService(rows,clock),codec,new PrivateFileStorage(System.getProperty("java.io.tmpdir")+"/accountdata-tests"),clock,new PrivateSnapshot(rows,new DataSourceTransactionManager(source),clock));}
    @Test void resetRequiresRecentPasswordAndMatchingRevision(){var body=Map.<String,Object>of("confirm","RESET","dataRevision",7);assertThrows(ApiProblem.class,()->service.reset(user,body,"account-reset-first",null));assertThrows(ApiProblem.class,()->service.reset(user,Map.of("confirm","RESET","dataRevision",6),"account-reset-conflict",clock.millis()+5000));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM tasks",Integer.class));assertEquals("IDLE",db.queryForObject("SELECT data_operation FROM users",String.class));}
    @Test void acceptedResetPersistsTaskOutboxAndFreezeWithoutAdvancingRevision(){var task=service.reset(user,Map.of("confirm","RESET","dataRevision",7),"account-reset-valid",clock.millis()+5000);assertNotNull(task);assertEquals("RESETTING",db.queryForObject("SELECT data_operation FROM users",String.class));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM tasks",Integer.class));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM outbox_events",Integer.class));assertEquals(7,db.queryForObject("SELECT data_revision FROM users",Integer.class));}
    @Test void exportsEnforceThreeDailyRequestsAndReplayDoesNotConsumeQuota(){String first="first-export-request";Object saved=service.export(user,Map.of("includeFiles",true),first);assertEquals(saved,service.export(user,Map.of("includeFiles",true),first));for(String key:List.of("second-export-request","third-export-request"))service.export(user,Map.of("includeFiles",false),key);assertEquals(3,db.queryForObject("SELECT COUNT(*) FROM tasks",Integer.class));assertEquals(429,assertThrows(ApiProblem.class,()->service.export(user,Map.of("includeFiles",false),"fourth-export-request")).status());}
    @Test void expiredIdempotencyKeyCanStartANewResetInsteadOfReturningOldTask(){String key="repeat-reset-after-day";var body=Map.<String,Object>of("confirm","RESET","dataRevision",7);service.reset(user,body,key,clock.millis()+5000);db.update("UPDATE users SET data_operation='IDLE'");db.update("UPDATE idempotency_records SET expires_at=?",new java.sql.Timestamp(0));service.reset(user,body,key,clock.millis()+5000);assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM tasks",Integer.class));assertEquals("RESETTING",db.queryForObject("SELECT data_operation FROM users",String.class));}

}
